// Diagnostic, run directly in the image (not through the system): what the
// delivered Target Tap page loads and does when opened the way the checks
// runner opens it, against the same tree served over loopback HTTP, and against
// a copy whose script and stylesheet paths are made relative.
const { test, expect } = await import(process.env.BW_PLAYWRIGHT_TEST);
import { createServer } from "node:http";
import { cpSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { extname, join } from "node:path";

function watch(page) {
  const events = [];
  page.on("console", (m) => events.push(`console.${m.type()}: ${m.text()}`));
  page.on("pageerror", (e) => events.push(`pageerror: ${e.message}`));
  page.on("requestfailed", (r) => events.push(`requestfailed: ${r.url()} ${r.failure()?.errorText}`));
  page.on("requestfinished", (r) => events.push(`requestfinished: ${r.url()}`));
  return events;
}

async function observe(page, url, events) {
  await page.goto(url);
  await page.waitForLoadState("load");
  await page.waitForTimeout(1000);
  const message = await page.locator("#message").textContent();
  await page.locator("#start").click();
  await page.waitForTimeout(500);
  const startHidden = await page.locator("#start").isHidden();
  console.log(JSON.stringify({ url, message, startHiddenAfterClick: startHidden, events }, null, 1));
}

test("file: as the checks runner opens it", async ({ page }) => {
  const events = watch(page);
  await observe(page, "file:///work/index.html", events);
  await expect(page.locator("body")).toBeVisible();
});

test("http: the same tree over loopback", async ({ page }) => {
  const types = { ".html": "text/html", ".js": "text/javascript", ".css": "text/css" };
  const server = createServer((req, res) => {
    try {
      const body = readFileSync(join("/work", decodeURIComponent(new URL(req.url, "http://x").pathname)));
      res.writeHead(200, { "content-type": types[extname(req.url)] ?? "application/octet-stream" });
      res.end(body);
    } catch {
      res.writeHead(404);
      res.end();
    }
  });
  await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));
  try {
    const events = watch(page);
    await observe(page, `http://127.0.0.1:${server.address().port}/index.html`, events);
  } finally {
    server.close();
  }
  await expect(page.locator("body")).toBeVisible();
});

test("file: a copy with relative script and stylesheet paths", async ({ page }) => {
  mkdirSync("/tmp/relative", { recursive: true });
  cpSync("/work/src", "/tmp/relative/src", { recursive: true });
  const html = readFileSync("/work/index.html", "utf8").replace('href="/src/styles.css"', 'href="src/styles.css"').replace('src="/src/main.js"', 'src="src/main.js"');
  writeFileSync("/tmp/relative/index.html", html);
  const events = watch(page);
  await observe(page, "file:///tmp/relative/index.html", events);
  await expect(page.locator("body")).toBeVisible();
});
